-- Superadministración: catálogo de módulos funcionales publicables para
-- usuarios no administrativos. La autorización granular sigue en RBAC.

CREATE TABLE "modulos_plataforma" (
    "id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "clave" TEXT NOT NULL,
    "etiqueta" TEXT NOT NULL,
    "descripcion" TEXT,
    "grupo" TEXT NOT NULL,
    "icono" TEXT NOT NULL,
    "orden" INTEGER NOT NULL DEFAULT 0,
    "habilitado_no_administradores" BOOLEAN NOT NULL DEFAULT true,
    "bloqueable_no_administradores" BOOLEAN NOT NULL DEFAULT true,
    "creado_en" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "actualizado_en" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "modulos_plataforma_pkey" PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX "modulos_plataforma_clave_key" ON "modulos_plataforma"("clave");
CREATE INDEX "modulos_plataforma_grupo_orden_idx" ON "modulos_plataforma"("grupo", "orden");

