INSERT INTO "roles"
  ("codigo", "nombre", "descripcion", "rango", "es_operativo", "es_sistema", "activo", "creado_en", "actualizado_en")
VALUES
  (
    'Superadministrador',
    'Superadministrador',
    'Controla la publicación visual de módulos y conserva acceso completo a la administración de la plataforma.',
    6,
    false,
    true,
    true,
    CURRENT_TIMESTAMP,
    CURRENT_TIMESTAMP
  )
ON CONFLICT ("codigo") DO UPDATE SET
  "nombre" = EXCLUDED."nombre",
  "descripcion" = EXCLUDED."descripcion",
  "rango" = EXCLUDED."rango",
  "es_sistema" = true,
  "activo" = true,
  "actualizado_en" = CURRENT_TIMESTAMP;

INSERT INTO "permisos"
  ("codigo", "modulo", "accion", "etiqueta", "descripcion", "activo", "creado_en")
VALUES
  ('publicacion_modulos:ver', 'publicacion_modulos', 'ver', 'Ver publicación de módulos', 'Consultar qué módulos están publicados para usuarios no administrativos.', true, CURRENT_TIMESTAMP),
  ('publicacion_modulos:configurar', 'publicacion_modulos', 'configurar', 'Configurar publicación de módulos', 'Habilitar u ocultar módulos para usuarios no administrativos.', true, CURRENT_TIMESTAMP)
ON CONFLICT ("codigo") DO UPDATE SET
  "modulo" = EXCLUDED."modulo",
  "accion" = EXCLUDED."accion",
  "etiqueta" = EXCLUDED."etiqueta",
  "descripcion" = EXCLUDED."descripcion",
  "activo" = true;

-- El Superadministrador hereda todos los permisos existentes.
INSERT INTO "roles_permisos" ("rol_id", "permiso_id")
SELECT r."id", p."id"
FROM "roles" r
CROSS JOIN "permisos" p
WHERE r."codigo" = 'Superadministrador'
ON CONFLICT ("rol_id", "permiso_id") DO NOTHING;
